type Customer struct { ID int64; Name string }   // plain domain type: no tags, no SQL

type CustomerMapper struct{ db *sql.DB }          // the mapper holds the connection, not the model

func (m *CustomerMapper) Find(ctx context.Context, id int64) (*Customer, error) {
	var c Customer
	err := m.db.QueryRowContext(ctx,
		"SELECT id, name FROM customers WHERE id = $1", id).Scan(&c.ID, &c.Name)
	if errors.Is(err, sql.ErrNoRows) { return nil, ErrNotFound }
	return &c, err
}

