type Customer struct {
	ID   int64  `db:"id"`
	Name string `db:"name"`            // tags couple the struct to column names
}

func (m *CustomerMapper) Find(ctx context.Context, id int64) (*Customer, error) {
	var c Customer
	err := m.db.GetContext(ctx, &c,
		"SELECT id, name FROM customers WHERE id = $1", id)
	return &c, err
}
